sysevent_script_action.script:
var new_state = event.parm1;
var content = event.parm2;
var mocs_group = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs');
var gr = new GlideRecord("x_hsb11_hsbcmss_eh_hsbc_email_case_task");
gr.get(current.sys_id);
if (new_state=="3"){
	gr.swb_id=content;
} else {
	var taskId = gr.number;
	var pShortdesc = gr.short_description;
	gr.work_notes="Error while attempting to call SWB";
	var grm = new GlideRecord("x_hsb11_hsbcmss_eh_hsbc_email_case_task");
	grm.initialize();
	grm.task_type="Manually Process Email";
	grm.short_description=taskId + " for " + pShortdesc + " " + gs.getProperty('x_hsb11_hsbc_mss_t.hsbc.short.description.mocs');
	grm.parent=gr.parent;
	grm.qtrack_id=gr.qtrack_id;
	grm.swb_id=gr.swb_id;
	grm.assignment_group=mocs_group;
	grm.state='1';
	grm.insert();
}
	gr.state=new_state;
	gr.update();
